# c16 三つ巴の要衝 - キャンペーン用の3陣営乱戦。
# 陣営0(自軍) / 陣営1(東方連邦) / 陣営2(南方連合) がそれぞれ独立。
# team 指定が無いので team[p]=p、つまりAI同士も戦う。
# 地形は m05_threeway と同じ。中央の高地と拠点群を奪い合う。
[map]
name             = 三つ巴の要衝
width            = 40
height           = 30
turns            = 90
timeout_winner   = -1
funds0           = 2600
funds1           = 3000
funds2           = 3000
# 拠点確保でも勝てるようにする。三つ巴で「2陣営とも完全に潰す」だけだと
# ターン上限の引き分け＝作戦失敗になりやすい。拠点は全部28個。
objective_count  = 17
objective_player = 0

